/**
 * Generated by dsh-session-cloudsync.
 *
 * 远端覆盖本地：备份本地会话、删除本地 artifact、清理插件/工作区状态。
 * 只应在 DSH 完全关闭后运行；本脚本会先检查生成它的 DSH PID 是否还活着。
 */
import { createHash } from 'node:crypto'
import {
  cp, mkdir, readdir, readFile, rename, rm, stat, writeFile,
} from 'node:fs/promises'
import { basename, dirname, join, relative, resolve } from 'node:path'

const CONFIG = __CONFIG__

function fail(message, code = 1) {
  console.error('')
  console.error(`[失败] ${message}`)
  console.error('')
  process.exit(code)
}

function ok(message) {
  console.log(`[ok] ${message}`)
}

function warn(message) {
  console.warn(`[警告] ${message}`)
}

async function exists(path) {
  try {
    await stat(path)
    return true
  } catch (error) {
    if (error?.code === 'ENOENT') return false
    throw error
  }
}

function checkDshStopped() {
  try {
    process.kill(CONFIG.dshPid, 0)
    fail(`DSH 仍在运行（PID ${CONFIG.dshPid}）。请先完全退出 DSH，再运行此脚本。`)
  } catch (error) {
    if (error?.code !== 'ESRCH') {
      fail(`无法确认 DSH 是否已关闭：${String(error)}。请确认进程 PID ${CONFIG.dshPid} 已退出后重试。`)
    }
  }
  ok('DSH 进程已关闭')
}

async function findSessionDir() {
  const root = join(CONFIG.dshHome, 'sessions')
  if (!(await exists(root))) fail(`找不到 DSH sessions 目录：${root}`)
  const projects = await readdir(root, { withFileTypes: true })
  const found = []
  for (const project of projects) {
    if (!project.isDirectory()) continue
    const candidate = join(root, project.name, CONFIG.sessionId)
    if (await exists(candidate)) {
      const info = await stat(candidate)
      if (info.isDirectory()) found.push(candidate)
    }
  }
  if (found.length === 0) fail(`找不到本地会话目录：${CONFIG.sessionId}`)
  if (found.length > 1) {
    fail(`找到多个同 id 的会话目录，拒绝猜测：\n${found.join('\n')}`)
  }
  const sessionDir = found[0]
  const rel = relative(resolve(root), resolve(sessionDir))
  if (rel.startsWith('..') || rel === '' || rel.includes('..' + requireSeparator())) {
    fail(`会话目录不在 sessions 根目录内，拒绝操作：${sessionDir}`)
  }
  ok(`找到本地会话目录：${sessionDir}`)
  return sessionDir
}

function requireSeparator() {
  return process.platform === 'win32' ? '\\' : '/'
}

async function listFiles(root) {
  const files = []
  async function walk(dir) {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name)
      if (entry.isDirectory()) await walk(full)
      else if (entry.isFile()) files.push(full)
    }
  }
  await walk(root)
  files.sort()
  return files
}

async function hashFile(file) {
  return createHash('sha256').update(await readFile(file)).digest('hex')
}

async function backupAndVerify(sourceDir) {
  await mkdir(CONFIG.backupRoot, { recursive: true })
  const stamp = new Date().toISOString().replace(/[:.]/g, '-')
  const finalDir = join(CONFIG.backupRoot, `${CONFIG.sessionId}-${stamp}`)
  const staging = `${finalDir}.partial`
  await rm(staging, { recursive: true, force: true })
  await mkdir(dirname(staging), { recursive: true })
  await cp(sourceDir, staging, { recursive: true, force: false, errorOnExist: true })

  const sourceFiles = await listFiles(sourceDir)
  const hasLog = sourceFiles.some((file) => /^session\.v\d+\.jsonl(?:\.zstd)?$/.test(basename(file)))
  if (!hasLog) fail(`本地目录里没有 session.v<N>.jsonl[.zstd] 日志，拒绝备份：${sourceDir}`)
  const backupFiles = await listFiles(staging)
  if (sourceFiles.length !== backupFiles.length) {
    fail(`备份文件数量不一致：源 ${sourceFiles.length}，备份 ${backupFiles.length}`)
  }

  const manifest = {
    sessionId: CONFIG.sessionId,
    createdAt: CONFIG.createdAt,
    formatVersion: CONFIG.formatVersion,
    createdAtIso: new Date(CONFIG.createdAt).toISOString(),
    sourceDir,
    backupDir: finalDir,
    files: [],
  }
  for (const source of sourceFiles) {
    const rel = relative(sourceDir, source)
    const target = join(staging, rel)
    if (!(await exists(target))) fail(`备份缺少文件：${rel}`)
    const sourceHash = await hashFile(source)
    const backupHash = await hashFile(target)
    if (sourceHash !== backupHash) fail(`备份校验失败：${rel}`)
    const info = await stat(source)
    manifest.files.push({ path: rel, bytes: info.size, sha256: sourceHash })
  }

  const stateBackup = join(staging, '_plugin-state.json')
  if (await exists(CONFIG.statePath)) {
    await cp(CONFIG.statePath, stateBackup, { force: true })
  }
  const workspaceBackup = join(staging, '_workspace.json')
  if (await exists(CONFIG.workspaceFile)) {
    await cp(CONFIG.workspaceFile, workspaceBackup, { force: true })
  }

  await writeFile(join(staging, '_backup-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`, 'utf8')
  await rename(staging, finalDir)
  ok(`本地已备份并校验：${finalDir}`)
  return finalDir
}

function parseJson(text, what) {
  try {
    return JSON.parse(text)
  } catch {
    fail(`${what} 不是合法 JSON，未做任何删除。`)
  }
}

async function prepareStateCleanup() {
  if (!(await exists(CONFIG.statePath))) return undefined
  const state = parseJson(await readFile(CONFIG.statePath, 'utf8'), '插件状态文件')
  if (state === null || typeof state !== 'object' || Array.isArray(state)) {
    fail('插件状态文件格式异常，未做任何删除。')
  }
  const id = CONFIG.sessionId
  if (Array.isArray(state.blocked)) state.blocked = state.blocked.filter((entry) => entry?.sessionId !== id)
  if (Array.isArray(state.blockedDecisions)) state.blockedDecisions = state.blockedDecisions.filter((entry) => entry?.sessionId !== id)
  if (Array.isArray(state.cwdPending)) state.cwdPending = state.cwdPending.filter((entry) => entry !== id)
  if (state.pending?.sessionId === id) delete state.pending
  state.revision = 0
  return state
}

async function prepareWorkspaceCleanup() {
  if (!(await exists(CONFIG.workspaceFile))) return undefined
  const workspace = parseJson(await readFile(CONFIG.workspaceFile, 'utf8'), '工作区记录')
  if (workspace === null || typeof workspace !== 'object' || Array.isArray(workspace)) {
    fail('工作区记录格式异常，未做任何删除。')
  }
  const id = CONFIG.sessionId
  const remove = (ids) => Array.isArray(ids) ? ids.filter((entry) => entry !== id) : ids
  if (workspace.global !== undefined) {
    workspace.global.archivedSessionIds = remove(workspace.global.archivedSessionIds)
  }
  if (workspace.tables?.workspaces !== undefined && workspace.tables.workspaces !== null) {
    for (const record of Object.values(workspace.tables.workspaces)) {
      if (record !== null && typeof record === 'object') record.sessionIds = remove(record.sessionIds)
    }
  }
  return workspace
}

async function writeJsonAtomic(path, value) {
  await mkdir(dirname(path), { recursive: true })
  const staging = `${path}.cloudsync.tmp`
  await writeFile(staging, `${JSON.stringify(value, null, 2)}\n`, 'utf8')
  await rename(staging, path)
}

async function removeLocal(sourceDir) {
  await rm(sourceDir, { recursive: true, force: false })
  if (await exists(sourceDir)) fail(`删除后本地会话目录仍然存在：${sourceDir}`)
  ok(`已移除本地会话目录：${sourceDir}`)

  if (await exists(CONFIG.projectionCacheFile)) {
    await rm(CONFIG.projectionCacheFile, { force: true })
    ok('已移除会话投影缓存')
  }
}

async function main() {
  console.log('')
  console.log('dsh-session-cloudsync · 远端覆盖本地')
  console.log(`会话：${CONFIG.sessionId}`)
  console.log(`生命周期：createdAt=${CONFIG.createdAt} formatVersion=${CONFIG.formatVersion}`)
  console.log('')

  checkDshStopped()
  const sourceDir = await findSessionDir()

  // 先解析，确认配置可写，再开始备份/删除。
  const nextState = await prepareStateCleanup()
  const nextWorkspace = await prepareWorkspaceCleanup()

  const backupDir = await backupAndVerify(sourceDir)

  await removeLocal(sourceDir)

  if (nextState !== undefined) {
    await writeJsonAtomic(CONFIG.statePath, nextState)
    ok('已清理同步插件的 blocked / 忽略 / cwd 待处理状态，并重置同步游标')
  } else {
    warn('没有找到同步插件状态文件，跳过插件状态清理')
  }

  if (nextWorkspace !== undefined) {
    await writeJsonAtomic(CONFIG.workspaceFile, nextWorkspace)
    ok('已移除工作区归档/会话记账中的该会话')
  } else {
    warn('没有找到 workspace.json，跳过工作区记录清理')
  }

  console.log('')
  console.log('完成。')
  console.log(`备份保留在：${backupDir}`)
  console.log('')
  console.log('下一步：启动 DSH。')
  console.log('插件会按重置后的游标重新读取远端；也可以打开同步气泡点击「立即同步」。')
  console.log('远端会按同一 sessionId / createdAt / formatVersion 全量重建本地会话。')
  console.log('如果远端已经不是同一生命周期，插件会把它作为新会话处理，不会覆盖成旧代。')
  console.log('')
}

main().catch((error) => {
  fail(error instanceof Error ? error.message : String(error))
})
